import json
import logging
import os
from pathlib import Path

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse

from .engine import (DEFAULT_THRESHOLD, MODEL_VERSION, Engine, file_fingerprint,
                     load_members)
from .schemas import AskRequest, AskResponse, MemberSummary

ROOT = Path(__file__).resolve().parent.parent
log = logging.getLogger("agrisoko")
LIMITATIONS = [
    "Answers come only from the approved members.json; nothing is generated by an external AI.",
    "Vocabulary-based retrieval: synonyms and misspellings beyond character n-grams may be missed.",
    "Questions about topics outside the member records return a no-match response.",
    "Only the group's own members are covered.",
]


def create_app(members_path: str | Path | None = None, threshold: float | None = None) -> FastAPI:
    path = Path(members_path or os.getenv("MEMBERS_PATH", ROOT / "data" / "members.json"))
    thr = threshold if threshold is not None else float(os.getenv("CONFIDENCE_THRESHOLD", DEFAULT_THRESHOLD))
    group = os.getenv("GROUP_CODE", "G08")
    meta_path = ROOT / "data" / "model_meta.json"
    commit = os.getenv("BUILD_COMMIT")
    if not commit and meta_path.exists():
        commit = json.loads(meta_path.read_text()).get("build_commit")
    commit = commit or "unknown"

    app = FastAPI(title=f"AgriSoko Pocket {group} API", version="1.0.0")
    engine: Engine | None = None
    fingerprint = "unavailable"
    try:
        members = load_members(path)
        fingerprint = file_fingerprint(path)
        engine = Engine(members, thr)
    except Exception as exc:  # empty / invalid dataset -> degraded, not crashed
        log.error("Dataset could not be loaded: %s", exc)

    def need_engine() -> Engine:
        if engine is None:
            raise HTTPException(status_code=503, detail="Member dataset is unavailable")
        return engine

    @app.exception_handler(Exception)
    async def safe_errors(_: Request, exc: Exception):
        log.exception("Unhandled error")
        return JSONResponse(status_code=500, content={"detail": "Internal server error"})

    @app.get("/health")
    def health():
        return {"status": "ok" if engine else "degraded", "version": app.version,
                "group_code": group, "model_version": MODEL_VERSION}

    @app.get("/members", response_model=list[MemberSummary])
    def members_list():
        return [MemberSummary(id=m["id"], fullName=m["fullName"], aliases=m["aliases"],
                              role=m["role"], feature=m["feature"]) for m in need_engine().members]

    @app.get("/members/{member_id}")
    def member_detail(member_id: str):
        for m in need_engine().members:
            if m["id"] == member_id:
                return m
        raise HTTPException(status_code=404, detail="Member not found")

    @app.post("/ask", response_model=AskResponse)
    def ask(req: AskRequest):
        res = need_engine().search(req.query)
        m = res["member"]
        log.info("ask matched=%s confidence=%s", res["matched"], res["confidence"])
        return AskResponse(
            query=res["query"], matched=res["matched"], confidence=res["confidence"],
            threshold=res["threshold"], reason=res["reason"], matched_terms=res["matched_terms"],
            member=MemberSummary(id=m["id"], fullName=m["fullName"], aliases=m["aliases"],
                                 role=m["role"], feature=m["feature"]) if m else None,
            introduction=res["introduction"],
            evidence_links=m["evidenceLinks"] if m else [],
            suggestions=res["suggestions"], model_version=MODEL_VERSION, group_code=group)

    @app.get("/model-info")
    def model_info():
        e = need_engine()
        return {"model_version": MODEL_VERSION,
                "vectorizer": "TF-IDF word(1-2) 0.6 + char_wb(3-5) 0.4, cosine similarity, name/alias boost +0.50",
                "threshold": e.threshold, "dataset_fingerprint_sha256": fingerprint,
                "member_count": len(e.members), "limitations": LIMITATIONS,
                "build_commit": commit, "group_code": group}

    return app


app = create_app()
